import json, urllib.request, re
token = json.load(open("/Users/mac/.claude.json"))["mcpServers"]["dc-platform"]["env"]["DC_USER_TOKEN"]
base = "http://54.255.236.159:8012"
headers={"Authorization": f"Bearer {token}"}

def get_sql(env, project, wf, task):
    url = f"{base}/api/v1/dolphin/projects/{project}/workflows/{wf}/tasks/{task}/sql?env={env}"
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=60) as resp:
        data = json.load(resp)
    return data.get("sql") or ""

def enroll_block(sql):
    # from WITH reg_enroll / elig through closing of that CTE
    m = re.search(r"((?:reg_enroll|elig)\s+AS\s*\((?:[^()]|\([^()]*\))*?\))\s*,", sql, re.S|re.I)
    if m: return m.group(1)
    # fallback: lines around install join
    lines = sql.splitlines()
    out=[]; grab=False; depth=0
    for i,l in enumerate(lines):
        if re.search(r'(reg_enroll|elig)\s+AS\s*\(', l, re.I):
            grab=True
        if grab:
            out.append(l)
            depth += l.count('(')-l.count(')')
            if depth<=0 and len(out)>3:
                break
    return '\n'.join(out[:80])

